(window.TNQ=window.TNQ||[]).push({"terms":{"과도기적":{"d":"한 상태에서 다른 상태로 넘어가는 중간 단계의 성격.","r":[]},"추상적 사고":{"d":"눈에 보이지 않는 개념을 머릿속에서 다루는 사고.","r":[]},"또래집단":{"d":"나이와 처지가 비슷한 친구들의 무리로 청소년기에 영향력이 커진다.","r":["동조성"]},"성장급등":{"d":"청소년기에 키와 몸이 갑자기 크게 자라는 현상.","r":[]},"미시체계":{"d":"청소년이 직접 상호작용하는 환경.","r":["외체계"]},"외체계":{"d":"청소년이 직접 참여하지 않지만 영향을 받는 환경으로 정부기관이 해당한다.","r":["미시체계"]},"내분비선":{"d":"호르몬을 혈액으로 내보내는 기관으로 이차 성징과 관련이 깊다.","r":[]},"초자아":{"d":"프로이트가 말한 성격 구조에서 도덕성을 담당하는 부분.","r":[]},"동조성":{"d":"집단의 의견이나 행동을 따르려는 경향.","r":["또래집단"]},"자아정체감":{"d":"자신이 누구인지에 대한 일관된 인식.","r":["또래집단"]},"사회학습이론":{"d":"관찰과 모방을 통해 행동이 학습된다고 보는 이론.","r":[]},"배려 지향적":{"d":"관계와 돌봄을 중심에 두는 도덕성의 방향.","r":[]},"생활관":{"d":"주거 연계와 자립 지원 서비스를 제공하는 시설로 입소는 사례심의위원회가 결정한다.","r":["사례심의위원회"]},"사례심의위원회":{"d":"생활관 입소 여부를 결정하는 위원회.","r":["생활관"]},"청소년증":{"d":"9세 이상 18세 이하의 청소년에게 발급하는 증표로 양도·대여가 금지된다.","r":[]},"전담기구":{"d":"통합지원체계의 운영을 맡도록 광역시 등이 설치하는 기구.","r":[]},"위기청소년":{"d":"조기에 발견하여 보호해야 하는 위험에 처한 청소년.","r":[]}},"notes":{"9세 이상 18세 이하의 청소년에게 발급한다":"청소년증은 9세 이상 18세 이하 청소년이 받을 수 있습니다.","가해자 중에서 학교폭력을 행사하거나 그 행위에 가담한 학생을 말한다":"가해학생은 학교폭력을 직접 행사했거나 그 행위에 가담한 학생입니다.","과도하면 청소년의 학업수행에 부정적인 영향을 미친다":"시험불안이 지나치면 청소년의 학업수행이 오히려 나빠집니다.","관할구역의 위기청소년을 조기에 발견하여 보호하고, 청소년복지 및 청소년보호를 효율적으로 수행함을 목적으로 한다":"청소년복지 지원법은 위기청소년을 일찍 발견해 보호하고 복지와 보호를 효율적으로 수행하려는 법입니다.","광역시는 전담기구를 설치할 수 있다":"광역시는 통합지원체계를 맡을 전담기구를 둘 수 있습니다.","국가는 구축ㆍ운영을 지원하여야 한다":"통합지원체계의 구축과 운영은 국가가 지원해야 합니다.","그 원인을 내부 요인보다 외부 요인으로 돌리는 경향이 있다":"학업 성취가 낮은 청소년은 원인을 자기 탓보다 바깥 요인 탓으로 돌리는 경향이 있습니다.","급격한 신체변화로 인해 자신의 체형에 대한 불만족을 느끼는 경우":"몸이 급격히 바뀌면서 자기 체형에 만족하지 못하는 일이 생기기도 합니다.","다른 사람들의 눈에 띄고 싶은 욕망으로부터 나온다":"자기중심적 사고는 남의 눈에 띄고 싶은 욕망에서 생겨납니다.","다른 사람에게 양도하거나 빌려주어서는 아니된다":"청소년증은 본인 것이므로 남에게 넘기거나 빌려줄 수 없습니다.","도덕성 발달 이론에 따르면 4단계는 법과 질서 지향의 단계이다":"콜버그의 이론에서 4단계는 법과 질서를 지키는 데 방향을 두는 단계입니다.","도덕성 발달이 초자아의 발현을 통해서 이루어진다고 보았다":"프로이트는 초자아가 나타나면서 도덕성이 발달한다고 보았습니다.","도덕적 행동 발달을 사회학습이론으로 설명하였다":"반두라는 관찰과 모방을 다루는 사회학습이론으로 도덕적 행동의 발달을 설명했습니다.","또래에 비해 신체적 발달이 빨리 이루어지는 경우":"신체적 조숙은 또래보다 몸의 발달이 일찍 진행되는 경우입니다.","또래집단에 대한 동조성이 높게 나타난다":"또래집단의 의견과 행동을 따르려는 동조성이 아동기보다 높습니다.","또래집단의 영향이 중요해지는 시기이다":"친구 무리인 또래집단이 미치는 영향이 점점 커집니다.","뚜렷해지는 것과 관련 깊은 내분비선":"이차 성징이 뚜렷해지는 일에는 내분비선이 깊이 관여합니다.","미시체계들 간의 관계성을 의미한다":"중간체계는 청소년이 속한 미시체계들 사이의 연결과 관계를 가리킵니다.","배려 지향적 도덕성 이론을 제시하였다":"길리건은 정의보다 배려를 중심에 둔 도덕성 이론을 내놓았습니다.","부모와 가족으로부터 자율성을 추구한다":"청소년은 부모와 가족에게서 벗어나 자율성을 얻으려 합니다.","사춘기에는 2차 성징이 나타나면서 성적 호기심이 증가한다":"사춘기에 2차 성징이 나타나는 것과 함께 성적 호기심도 커집니다.","생활관 입소는 사례심의위원회에서 결정한다":"생활관에 들어갈지는 사례심의위원회가 정합니다.","스스로 주인공이 되어 무대 위에 있는 것처럼 행동한다":"자기가 무대 위의 주인공인 것처럼 행동하기도 합니다.","신체적ㆍ정신적ㆍ지적 장애 등으로 「장애인 등에 대한 특수교육법」 제15조에서 규정하는 특수교육이 필요한 학생을 말한다":"장애학생은 장애 때문에 특수교육법상 특수교육이 필요하다고 규정된 학생입니다.","아동에서 성인으로 이행하는 과도기적인 단계이다":"청소년기는 아동도 성인도 아닌 중간에서 성인으로 넘어가는 과도기입니다.","여성가족부가 청소년증의 발급에 필요한 사항을 정한다":"발급 절차 같은 세부 사항은 여성가족부가 정합니다.","오늘날 청소년기는 더 연장되는 추세이다":"예전보다 청소년기로 보는 기간이 오늘날에는 길어지는 쪽입니다.","인터넷, 휴대전화 등 정보통신기기를 이용하여 학생들이 특정 학생들을 대상으로 지속적, 반복적으로 심리적 공격을 가하거나, 특정 학생과 관련된 개인정보 또는 허위사실을 유포하여 상대방이 고통을 느끼도록 하는 모든 행위를 말한다":"사이버 따돌림은 정보통신기기로 특정 학생에게 심리적 공격을 가하거나 허위사실을 퍼뜨려 고통을 주는 모든 행위입니다.","읽기, 쓰기, 셈하기 등의 기초학습영역에서 문제를 보이는 경우를 말한다":"학습장애는 읽기·쓰기·셈하기 같은 기초학습영역에서 어려움을 보이는 경우입니다.","자아정체감 형성의 기회를 제공한다":"또래관계는 자아정체감을 형성할 기회가 되어 줍니다.","전 생애에 걸쳐 일어나는 변화와 사회ㆍ역사적인 환경을 의미한다":"시간체계는 생애 동안의 변화와 그 시대의 사회ㆍ역사적 환경을 포함합니다.","정부기관은 외체계에 해당된다":"청소년이 직접 참여하지 않아도 영향을 받는 정부기관은 외체계에 속합니다.","주거 연계, 생활관 운영, 자립 지원 서비스를 지원한다":"생활관은 주거 연계와 시설 운영, 자립 지원 서비스를 지원하는 곳입니다.","청소년과 관련된 연령은 법령에 따라 다르다":"청소년을 몇 살로 보는지는 법령마다 기준이 다릅니다.","청소년기는 사춘기의 시작과 함께 시작한다":"청소년기의 출발점은 사춘기가 시작되는 시점입니다.","청소년기는 신체적 성장급등이 이루어지는 시기이다":"청소년기에는 키와 몸이 갑자기 크게 자라는 성장급등이 일어납니다.","청소년의 정신건강에 부정적인 영향을 미칠 수 있다":"이런 불만족은 청소년의 정신건강에 나쁜 영향을 줄 수 있습니다.","청소년이 직접 상호작용하는 환경을 포함한다":"미시체계는 가정, 학교처럼 청소년이 직접 접촉하는 환경입니다.","최근 사회변화에 따라 청소년기가 연장되는 추세에 있다":"사회가 변하면서 청소년기가 늘어나는 흐름이 최근에 나타납니다.","최초 3개월 이내에 거주할 수 있다":"처음 거주 기간은 3개월 이내입니다.","추상적 사고가 가능해지는 시기이다":"눈앞에 없는 개념도 머릿속에서 다룰 수 있는 추상적 사고가 이때 가능해집니다.","친구들과 많은 시간을 보낸다":"아동기보다 친구와 함께 지내는 시간이 훨씬 많아집니다.","타인들이 자신을 주시하고 있다고 생각한다":"다른 사람들이 늘 자기를 지켜본다고 믿는 경향이 있습니다.","특별자치시장ㆍ특별자치도지사 또는 시장ㆍ군수ㆍ구청장이 발급할 수 있다":"발급은 특별자치시장, 특별자치도지사, 시장·군수·구청장이 할 수 있습니다.","필요시 추가 3개월 1회 연장 가능하다":"필요하면 3개월을 한 번 더 늘릴 수 있습니다.","학교폭력으로 인하여 피해를 입은 학생을 말한다":"피해학생은 학교폭력 때문에 피해를 본 학생을 가리킵니다."}});if(window.DIAGRAM&&DIAGRAM.tnFlush)DIAGRAM.tnFlush();
/*tnote-data-end*/
